from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _dependency_solver(data, descending_names, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=descending_names)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[None] + list(packages[name]) for name in names]
    best_vector = None
    best_versions = None

    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        valid = True
        for name, bounds in data["roots"].items():
            row = selected.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        closure = set(data["roots"])
        edges = {name: [] for name in selected}
        stack = list(data["roots"])
        while stack and valid:
            name = stack.pop()
            row = selected.get(name)
            if row is None:
                valid = False
                break
            version = row["version"]
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                edges[name].append(other)
                other_row = selected.get(other)
                if (other_row is None or not dep["min"] <= other_row["version"] <= dep["max"]):
                    valid = False
                    break
                if other not in closure:
                    closure.add(other)
                    stack.append(other)
        if not valid or closure != set(selected):
            continue

        finished, active = set(), set()
        def visit(node):
            if node in active:
                return False
            if node in finished:
                return True
            active.add(node)
            if any(not visit(child) for child in edges.get(node, [])):
                return False
            active.remove(node)
            finished.add(node)
            return True

        if not all(visit(node) for node in selected):
            continue
        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best_versions = {name: row["version"] for name, row in selected.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _build_dependency(descending_names, maximize):
    return lambda data: _dependency_solver(data, descending_names, maximize)


def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("sequence", 0), event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for selected in product((False, True), repeat=len(jobs)):
        subset = [job for job, take in zip(jobs, selected) if take]
        if len(subset) != k:
            continue
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        id_list = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit_for.get(start_node, 0)
    initial = (start_node, data["coupons"], start_mask)
    distances = {initial: data["start"]}
    queue = [(data["start"], start_node, data["coupons"], start_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_remaining, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_remaining, next_mask))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency(True, False),
    "component_02": _build_dependency(False, True),
    "component_03": _build_dependency(False, False),
    "component_04": _build_dependency(True, True),
    "component_05": _build_dependency(True, False),
    "component_06": _ledger,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
